import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"大畜","description":"周易正义 - 大畜","frontmatter":{"title":"大畜","description":"周易正义 - 大畜"},"headers":[],"relativePath":"zh/classics/zhengyi/026.md","filePath":"zh/classics/zhengyi/026.md"}'),l={name:"zh/classics/zhengyi/026.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<blockquote><p>山天大畜</p></blockquote><blockquote><p>卦辞：利贞，不家食吉，利涉大川。</p></blockquote><blockquote><p>彖曰：大畜，刚健笃实，辉光日新。其德刚上而尚贤，能止健，大正也。不家食吉，养贤也。利涉大川，应乎天也。</p></blockquote><h1 id="大畜" tabindex="-1">大畜 <a class="header-anchor" href="#大畜" aria-label="Permalink to “大畜”">​</a></h1><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：谓之“大畜”者，乾健上进，艮止在上，止而畜之，能畜止刚健，故曰“大畜”。《彖》云：“能止健，大正”也。是能止健，故为大畜也。小畜则巽在乾上，以其巽顺，不能畜止乾之刚，故云小畜也。此则艮能止之，故为大畜也。“利贞”者，人能止健，非正不可，故“利贞”也。“不家食吉”者，己有大畜之资，当须养顺贤人，不使贤人在家自食，如此乃吉也。“利涉大川”者，丰则养贤，应於天道，不忧险难，故“利涉大川”。</p><h2 id="《彖》曰-​" tabindex="-1">《彖》曰： ​ <a class="header-anchor" href="#《彖》曰-​" aria-label="Permalink to “《彖》曰： ​”">​</a></h2><h3 id="《大畜》-刚健笃实-辉光日新其德。-​" tabindex="-1">《大畜》，刚健笃实，辉光日新其德。 ​ <a class="header-anchor" href="#《大畜》-刚健笃实-辉光日新其德。-​" aria-label="Permalink to “《大畜》，刚健笃实，辉光日新其德。 ​”">​</a></h3><p>王弼：凡牧既厌而退者，弱也；既荣而陨者，薄也。夫能“辉光日新其德”者，唯“刚健笃实”也。</p><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：言“大畜刚健笃实”者，此释大畜之义，“刚健”谓乾也。乾体刚性健，故言“刚健”也。“笃实”，谓艮也。艮体静止，故称“笃实”也。“辉光日新其德”者，以其刚健笃实之故，故能辉耀光荣，日日增新其德。若无刚健，则劣弱也，必既厌而退。若无笃实，则虚薄也，必既荣而陨，何能久有辉光，日新其德乎？○注“凡物既厌”至“刚健笃实也”。○正义曰：“凡物既厌而退者，弱也”者，释《经》“刚健”也。若不刚健，则见厌被退。能刚健，则所为日进，不被厌退也。“既荣而陨者薄也”者，释《经》“笃实”也。凡物暂时荣华而即损落者，由体质虚薄也。若能笃厚充实，则恒保荣美，不有损落也。</p><h3 id="刚上而尚贤-​" tabindex="-1">刚上而尚贤， ​ <a class="header-anchor" href="#刚上而尚贤-​" aria-label="Permalink to “刚上而尚贤， ​”">​</a></h3><p>王弼：谓上九也。处上而大通，刚来而不距，“尚贤”之谓也。</p><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>“刚上而尚贤”。○正义曰：“刚上”谓上九也。乾刚向上，上九不距，是贵尚贤也。○注“谓上九”至“尚贤之谓也”。○正义曰：“谓上九也”者，言上九之德，见乾之上进而不距逆，是贵“尚贤”也。“处上而大通”者，释上九“何天之衢亨”，是处上通也。既处於上，下应於天，有大通之德也。“刚来而不距”者，以有大通，既见乾来而不距逆，是“尚贤”之义也。</p><h3 id="能止健-大正也。-​" tabindex="-1">能止健，大正也。 ​ <a class="header-anchor" href="#能止健-大正也。-​" aria-label="Permalink to “能止健，大正也。 ​”">​</a></h3><p>王弼：健莫过乾而能止之，非夫“大正”，未之能也。</p><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：释“利贞”义。所以艮能止乾之健者，德能大正，故“能止健”也。</p><h3 id="不家食吉-养贤也。-利涉大川-应乎天也。-​" tabindex="-1">“不家食吉”，养贤也。“利涉大川”，应乎天也。 ​ <a class="header-anchor" href="#不家食吉-养贤也。-利涉大川-应乎天也。-​" aria-label="Permalink to ““不家食吉”，养贤也。“利涉大川”，应乎天也。 ​”">​</a></h3><p>王弼：有大畜之实，以之养贤，令贤者不家食，乃吉也。“尚贤”制健，“大正”应天，不忧险难，故“利涉大川”也。</p><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>“不家食吉”至“应乎天也”。○正义曰：“不家食吉，养贤”者，释“不家食吉”，所以不使贤者在家自食而获吉也。以在上有“大畜”之实，养此贤人，故不使贤者在家自食也。“利涉大川应乎天”者，以贵尚贤人，大正应天，可逾越险难，故“利涉大川”也。○注“有大畜之实”至“利涉大川也”。○正义曰：“尚贤制健”者，谓上九刚来不距，“尚贤”之谓也。艮能畜刚，“制健”之谓也。故上《经》云：“刚上而尚贤”。王《注》云：“谓上九也。”又云：“能止健，大正也。”王《注》云：“健莫过乾，而能止之，非夫大正，未之能也。”则是全论艮体。“明知尚贤”，谓上九也。“制健”谓艮体也。“大正应天”者，谓艮也。故前文云：“能止健，大正也。”止健是艮也，应天者，上体之艮，应下体之乾，故称“应天”也。此取上卦、下卦而相应，非谓一阴一阳而相应也。</p><h2 id="《象》曰-天在山中-大畜。君子以多识前言往行-以畜其德。-​" tabindex="-1">《象》曰：天在山中，大畜。君子以多识前言往行，以畜其德。 ​ <a class="header-anchor" href="#《象》曰-天在山中-大畜。君子以多识前言往行-以畜其德。-​" aria-label="Permalink to “《象》曰：天在山中，大畜。君子以多识前言往行，以畜其德。 ​”">​</a></h2><p>王弼：物之可畜於怀，令德不散，尽於此也。</p><h3 id="疏-5" tabindex="-1">疏 <a class="header-anchor" href="#疏-5" aria-label="Permalink to “疏”">​</a></h3><p>“《象》曰”至“以畜其德”。○正义曰：“天在山中”者，欲取德积於身中，故云“天在山中”也。“君子以多识前言，往行以畜其德”者，君子则此“大畜”，物既“大畜”，德亦“大畜”，故多记识前代之言，往贤之行，使多闻多见，以畜积己德，故云“以畜其德”也。○注“物之可畜”至“尽於此也”。○正义曰：物之可畜於怀，令其道德不有弃散者，唯贮藏“前言往行”於怀，可以令德不散也。唯此而已，故云“尽於此也”。</p><h2 id="初九-有厉利巳。-​" tabindex="-1">初九：有厉利巳。 ​ <a class="header-anchor" href="#初九-有厉利巳。-​" aria-label="Permalink to “初九：有厉利巳。 ​”">​</a></h2><p>王弼：四乃畜巳，未可犯也。故进则有厉，已则利也。</p><h3 id="疏-6" tabindex="-1">疏 <a class="header-anchor" href="#疏-6" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：初九虽有应於四，四乃抑畜於己。己今若往，则有危厉。唯利休巳，不须前进，则不犯祸凶也。故《象》云：“不犯灾也。”</p><h3 id="《象》曰-有厉利巳-不犯灾也。-​" tabindex="-1">《象》曰：“有厉利巳”，不犯灾也。 ​ <a class="header-anchor" href="#《象》曰-有厉利巳-不犯灾也。-​" aria-label="Permalink to “《象》曰：“有厉利巳”，不犯灾也。 ​”">​</a></h3><p>王弼：处健之始，未果其健者，故能利巳。</p><h2 id="九二-舆说輹。-​" tabindex="-1">九二：舆说輹。 ​ <a class="header-anchor" href="#九二-舆说輹。-​" aria-label="Permalink to “九二：舆说輹。 ​”">​</a></h2><p>王弼：五处畜盛，未可犯也。遇斯而进，故“舆说輹”也。居得其中，能以其中不为冯河，死而无悔，遇难能止，故“无尤”也。</p><h3 id="疏-7" tabindex="-1">疏 <a class="header-anchor" href="#疏-7" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：九二虽与六五相应，“五处畜盛，未可犯也”。若遇斯而进，则舆说其輹，车破败也。以其居中，能遇难而止，则无尤过，故《象》云“中无尤”也。以其居中能自止息，故“无尤”也。此“舆说輹”，亦假象以明人事也。</p><h3 id="《象》曰-舆说輹-中无尤也。-​" tabindex="-1">《象》曰：“舆说輹”，中无尤也。 ​ <a class="header-anchor" href="#《象》曰-舆说輹-中无尤也。-​" aria-label="Permalink to “《象》曰：“舆说輹”，中无尤也。 ​”">​</a></h3><h2 id="九三-良马逐-利艰贞。曰-闲舆卫-利有攸往。-​" tabindex="-1">九三：良马逐，利艰贞。曰：闲舆卫，利有攸往。 ​ <a class="header-anchor" href="#九三-良马逐-利艰贞。曰-闲舆卫-利有攸往。-​" aria-label="Permalink to “九三：良马逐，利艰贞。曰：闲舆卫，利有攸往。 ​”">​</a></h2><p>王弼：凡物极则反，故畜极则通。初二之进，值於畜盛，故不可以升。至於九三，升于上九，而上九处天衢之亨，途径大通，进无违距，可以驰骋，故曰“良马逐”也。履当其位，进得其时，在乎通路，不忧险厄，故“利艰贞”也。闲，阂也。卫，护也。进得其时，虽涉艰难而无患也，舆虽遇闲而故卫也。与上合志，故“利有攸往”也。</p><h3 id="疏-8" tabindex="-1">疏 <a class="header-anchor" href="#疏-8" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“九三良马逐”者，“初二之进，值於畜盛”，不可以升。“至於九三，升于上九，而上九处天衢之亨，途径大通，进无违距”，故九三可以良马驰逐也。“利艰贞”者，“履当其位，进得其时，在乎通路，不忧险厄”，故宜利艰难而贞正也。若不值此时，虽平易守正而尚不可，况艰难而欲行正乎？“曰闲舆卫”者，进得其时，涉难无患，虽曰有人欲闲阂车舆，乃是防卫见护也，故云“曰闲舆卫”也。“利有攸往”者，与上合志，利有所往，故《象》曰“上合志”也。</p><h3 id="《象》曰-利有攸往-上合志也。-​" tabindex="-1">《象》曰：“利有攸往”，上合志也。 ​ <a class="header-anchor" href="#《象》曰-利有攸往-上合志也。-​" aria-label="Permalink to “《象》曰：“利有攸往”，上合志也。 ​”">​</a></h3><h2 id="六四-童牛之牿-元吉。-​" tabindex="-1">六四：童牛之牿，元吉。 ​ <a class="header-anchor" href="#六四-童牛之牿-元吉。-​" aria-label="Permalink to “六四：童牛之牿，元吉。 ​”">​</a></h2><p>王弼：处艮之始，履得其位，能止健初，距不以角，柔以止刚，刚不敢犯。抑锐之始，以息强争，岂唯独利？乃将“有喜”也。</p><h3 id="疏-9" tabindex="-1">疏 <a class="header-anchor" href="#疏-9" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“童牛之牿”者，处艮之始，履得其位，能抑止刚健之初。距此初九，不须用角，故用童牛牿止其初也。“元吉”者，柔以止刚，刚不敢犯，以息彊争所以大吉而有喜也，故《象》云“元吉，有喜也。”</p><h3 id="《象》曰-六四-元吉-有喜也。-​" tabindex="-1">《象》曰：六四“元吉”，有喜也。 ​ <a class="header-anchor" href="#《象》曰-六四-元吉-有喜也。-​" aria-label="Permalink to “《象》曰：六四“元吉”，有喜也。 ​”">​</a></h3><h2 id="六五-豮豕之牙-吉。-​" tabindex="-1">六五：豮豕之牙，吉。 ​ <a class="header-anchor" href="#六五-豮豕之牙-吉。-​" aria-label="Permalink to “六五：豮豕之牙，吉。 ​”">​</a></h2><p>王弼：豕牙横猾，刚暴难制之物，谓二也。五处得尊位，为畜之主。二刚而进，能豮其牙，柔能制健，禁暴抑盛，岂唯能固其位，乃将“有庆”也！</p><h3 id="疏-10" tabindex="-1">疏 <a class="header-anchor" href="#疏-10" aria-label="Permalink to “疏”">​</a></h3><p>“《象》曰”至“豮豕之牙吉”。○正义曰：“豮豕之牙”者，豕牙谓九二也。二既刚阳，似豕牙之横猾。九二欲进，此六五处得尊位，能豮损其牙，故云“豮豕之牙”。柔能制刚，禁暴抑盛，所以“吉”也。非唯独吉，乃终久有庆。故《象》云“六五之吉，有庆也”。○注“豕牙横猾”至“将有庆”。○正义曰：“能豮其牙者，观注意则豮是禁制损去之名褚氏云：“豮除也。除其牙也。然豮之为除，《尔雅》无训。案《尔雅》云：“坟，大防。”则坟是隄防之义。此“豮其牙”，谓防止其牙。古字假借，虽豕傍土边之异，其义亦通。“豮其牙”，谓止其牙也。</p><h3 id="《象》曰-六五之-吉-有庆也。-​" tabindex="-1">《象》曰：六五之“吉”，有庆也。 ​ <a class="header-anchor" href="#《象》曰-六五之-吉-有庆也。-​" aria-label="Permalink to “《象》曰：六五之“吉”，有庆也。 ​”">​</a></h3><h2 id="上九-何天之衢-亨。-​" tabindex="-1">上九：何天之衢，亨。 ​ <a class="header-anchor" href="#上九-何天之衢-亨。-​" aria-label="Permalink to “上九：何天之衢，亨。 ​”">​</a></h2><p>王弼：处畜之极，畜极则通，大畜以至於大亨之时。何，辞也，犹云何畜，乃天之衢亨也。</p><h3 id="疏-11" tabindex="-1">疏 <a class="header-anchor" href="#疏-11" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“何天之衢亨”者，何谓语辞，犹云“何畜”也。处畜极之时，更何所畜？乃天之衢亨，无所不通也。故《象》云：“何天之衢，道大行也”。何氏云：“天衢既通，道乃大亨。”</p><h3 id="《象》曰-何天之衢-道大行也。-​" tabindex="-1">《象》曰：“何天之衢”，道大行也。 ​ <a class="header-anchor" href="#《象》曰-何天之衢-道大行也。-​" aria-label="Permalink to “《象》曰：“何天之衢”，道大行也。 ​”">​</a></h3>',58)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
